input.sparql:
SELECT ?zone ?tempSeries ?heatSetpointSeries ?coolSetpointSeries
WHERE {
  ?zone brick(hasPoint|brickHasPoint) ?tempPoint ;
         rdfs:label 'DataCenter_mid_ZN_6'^^<http://www.w3.org/2001/XMLSchema#string> .
  ?tempPoint ref:hasTimeseriesId ?tempSeries ;
              (brick:isTimeseriesOf|brick:timeseries) brick:Zone_Air_Temperature_Sensor .
  ?zone brick:hasPoint|brick:brickHasPoint ?heatSetpointPoint, ?coolSetpointPoint .
  ?heatSetpointPoint ref:hasTimeseriesId ?heatSetpointSeries ;
                    (brick:isTimeseriesOf|brick:timeseries) brick:Heating_Setpoint .
  ?coolSetpointPoint ref:hasTimeseriesId ?coolSetpointSeries ;
                    (brick:isTimeseriesOf|brick:timeseries) brick:Cooling_Setpoint .
}
